const body = $input.first().json.body || $input.first().json;
const ticket = body.ticket || body;

// Extract custom fields
const customFields = ticket.custom_fields || [];
function getFieldValue(idKey, numericId) {
  const found = customFields.find(f => f.id === idKey || f.id === numericId || f.id === Number(numericId) || f.id === String(numericId));
  return found ? found.value : '';
}

return [{
  json: {
    ticket_id: ticket.id,
    requester_name: ticket.requester ? ticket.requester.name : 'Valued Customer',
    requester_email: ticket.requester ? ticket.requester.email : '',
    requester_phone: ticket.requester ? ticket.requester.phone : '',
    subject: ticket.subject,
    session_token: getFieldValue('hc_session_token', 17953452223503),
    fbclid: getFieldValue('hc_fbclid', 17953492031119),
    utm_source: getFieldValue('hc_utm_source', 17953470454671),
    utm_campaign: getFieldValue('hc_utm_campaign', 17953470092687),
    channel: getFieldValue('hc_contact_channel', 17953481428751) || 'WhatsApp',
    brand: getFieldValue('hc_brand') || 'Home Cartel'
  }
}];

